import type { ReactNode, SVGProps } from "react";

import { ChevronDownIcon as SharedChevronDownIcon, CloseIcon as SharedCloseIcon } from "../status-icons/icons";

/** 24px stroke icons used by the side drawer parts (decorative: always aria-hidden). */
type IconProps = Omit<SVGProps<SVGSVGElement>, "children">;

function Icon({ children, strokeWidth = 2, ...props }: IconProps & { children: ReactNode }) {
  return (
    <svg
      aria-hidden
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      {children}
    </svg>
  );
}

/**
 * A 24px stroke "x" icon.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @example
 * ```tsx
 * import { CloseIcon } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Close"><CloseIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function CloseIcon(props: IconProps) {
  return <SharedCloseIcon strokeWidth={2} {...props} />;
}

/**
 * A 24px stroke check mark inside a circle.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { CheckCircleIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Done"><CheckCircleIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function CheckCircleIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <circle cx="12" cy="12" r="9" />
      <path d="m8.5 12.5 2.5 2.5 4.5-5" />
    </Icon>
  );
}

/**
 * A 24px stroke chevron pointing up.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { ChevronUpIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Collapse"><ChevronUpIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function ChevronUpIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="m6 15 6-6 6 6" />
    </Icon>
  );
}

/**
 * A 24px stroke chevron pointing down.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { ChevronDownIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Expand"><ChevronDownIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function ChevronDownIcon(props: IconProps) {
  return <SharedChevronDownIcon {...props} />;
}

/**
 * A 24px stroke pencil (edit) icon.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { PencilIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Edit"><PencilIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function PencilIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M4 20h4L18.5 9.5a2.12 2.12 0 0 0-3-3L5 17v3z" />
      <path d="m13.5 8.5 3 3" />
    </Icon>
  );
}

/**
 * A 24px stroke "more" (three dots) icon.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { MoreIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="More actions"><MoreIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function MoreIcon(props: IconProps) {
  return (
    <Icon strokeWidth={3} {...props}>
      <path d="M5.5 12h.01M12 12h.01M18.5 12h.01" />
    </Icon>
  );
}

/**
 * A 24px stroke inbox icon.
 * Used by the side drawer parts; size it with a class such as `size-4`, it uses `currentColor`.
 * Accepts every `svg` prop except `children`.
 *
 * Keyboard: none. Accessibility: decorative, always `aria-hidden`; put the meaning in the surrounding
 * button's `aria-label` or text. Glass and motion: static, none.
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { InboxIcon } from "./icons";
 *
 * export function Example() {
 *   return (
 *     <button type="button" aria-label="Inbox"><InboxIcon className="size-4" /></button>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function InboxIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M3 13h5l1.5 2.5h5L16 13h5" />
      <path d="M5.5 5.5h13L21 13v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-5z" />
    </Icon>
  );
}

"use client";

import { useContext, useEffect, useRef, useState, type ComponentProps, type ReactNode, type Ref } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

import { cn, classNameWith } from "../../lib/cn";
import { useMergedRef } from "../../lib/form";
import { DrawerClose, DrawerTrigger } from "../../drawer/drawer";
import { SCROLL_REST, ScrollContext } from "./content";

/* ---------- Body ---------- */

/**
 * Props of `SideDrawerBody`: the Base UI `Drawer.Content` props plus SheenUI's own options, each
 * documented on its field.
 */
export type SideDrawerBodyProps = ComponentProps<typeof BaseDrawer.Content> & {
  /** Receives the ref to the scrolling element. */
  scrollRef?: Ref<HTMLDivElement>;
  /** Class for the outer wrapper (holds the scroll shadows). */
  wrapperClassName?: string;
};

/**
 * The scrolling part. Soft shadows appear at the top / bottom edge while there is more to scroll that way (drawn over the content, never a mask, so glass inside keeps its blur). `scrollRef` gives you the scrolling element;
 * `wrapperClassName` styles the wrapper that holds the shadows. Touch: vertical drags scroll, a horizontal swipe towards the edge closes the drawer.
 *
 * Keyboard: a tab stop only while it overflows, so keyboard users can scroll it with the arrows. Accessibility: gets `tabIndex=0` only when scrollable, with an inset focus ring. Glass and motion: shadows fade with opacity only.
 *
 * @example
 * ```tsx
 * import { DescriptionList, SideDrawerBody } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerBody>
 *       <DescriptionList items={[{ label: "Email", value: "ada@example.com" }]} />
 *     </SideDrawerBody>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerBody({ className, wrapperClassName, scrollRef, children, ...props }: SideDrawerBodyProps) {
  const { scroll, setScroll } = useContext(ScrollContext);
  const ref = useRef<HTMLDivElement | null>(null);
  const mergedBodyRef = useMergedRef(ref, scrollRef);
  const [overflows, setOverflows] = useState(false);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    let frame = 0;
    let last = "";
    const measure = () => {
      frame = 0;
      const max = element.scrollHeight - element.clientHeight;
      const atTop = element.scrollTop <= 1;
      const atBottom = element.scrollTop >= max - 1;
      const key = `${max > 1}|${atTop}|${atBottom}`;
      if (key === last) return;
      last = key;
      setOverflows(max > 1);
      setScroll({ atTop, atBottom });
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure);
    };
    measure();
    element.addEventListener("scroll", schedule, { passive: true });
    const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(schedule);
    const observeAll = () => {
      if (!resize) return;
      resize.disconnect();
      resize.observe(element);
      for (const child of Array.from(element.children)) resize.observe(child);
    };
    observeAll();
    const mutations = new MutationObserver(() => {
      observeAll();
      schedule();
    });
    mutations.observe(element, { childList: true, subtree: true });
    return () => {
      cancelAnimationFrame(frame);
      element.removeEventListener("scroll", schedule);
      resize?.disconnect();
      mutations.disconnect();
      setScroll(SCROLL_REST);
    };
  }, [setScroll]);

  return (
    <div data-slot="side-drawer-body-wrapper" className={cn("relative flex min-h-0 flex-1 flex-col", wrapperClassName)}>
      <BaseDrawer.Content
        ref={mergedBodyRef}
        data-slot="side-drawer-body"
        tabIndex={overflows ? 0 : undefined}
        className={classNameWith(className, (extra) =>
          cn(
            "min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 py-4 [scrollbar-width:thin] @sm/side-drawer:px-5",
            "touch-auto focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
            extra,
          ),
        )}
        {...props}
      >
        {children}
      </BaseDrawer.Content>
      {/* Scroll shadows: overlays (not a mask), so glass in the content keeps its blur. */}
      <span
        aria-hidden
        data-visible={!scroll.atTop || undefined}
        className="pointer-events-none absolute inset-x-0 top-0 h-5 bg-linear-to-b from-[var(--sheen-shadow-far)] to-transparent opacity-0 transition-opacity duration-(--sheen-duration-base) data-visible:opacity-45 forced-colors:hidden"
      />
      <span
        aria-hidden
        data-visible={!scroll.atBottom || undefined}
        className="pointer-events-none absolute inset-x-0 bottom-0 h-6 bg-linear-to-t from-[var(--sheen-shadow-far)] to-transparent opacity-0 transition-opacity duration-(--sheen-duration-base) data-visible:opacity-45 forced-colors:hidden"
      />
    </div>
  );
}

/* ---------- Footer ---------- */

/**
 * Props of `SideDrawerFooter`: the native `<div>` props plus its own options, each documented on its
 * field.
 */
export type SideDrawerFooterProps = ComponentProps<"div"> & {
  /** Content on the inline start: a hint ("Unsaved changes"), record navigation. */
  start?: ReactNode;
};

/**
 * Sticky footer: `start` on the inline start (a hint such as "Unsaved changes", record navigation), the buttons (children) on the other end. Gets the panel's width-aware padding.
 *
 * Keyboard: the buttons are normal tab stops. Accessibility: a plain `div`. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { Button, SideDrawerFooter } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerFooter start="Unsaved changes">
 *       <Button variant="ghost">Cancel</Button>
 *       <Button>Save</Button>
 *     </SideDrawerFooter>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerFooter({ start, className, children, ...props }: SideDrawerFooterProps) {
  return (
    <div
      data-slot="side-drawer-footer"
      className={cn(
        "flex shrink-0 flex-wrap items-center justify-end gap-x-3 gap-y-2 border-t border-sheen-border px-4 py-3 @sm/side-drawer:px-5",
        className,
      )}
      {...props}
    >
      {start && <div className="me-auto flex min-w-0 items-center gap-2">{start}</div>}
      {children && <div className="flex min-w-0 items-center gap-2">{children}</div>}
    </div>
  );
}

/** Props of {@link SideDrawerTrigger}. The element that opens a `SideDrawer` (a `<button>` by default; use `render={<Button />}` for a SheenUI button). */
export type SideDrawerTriggerProps = ComponentProps<typeof DrawerTrigger>;

/** Props of {@link SideDrawerClose}. Closes the drawer (through the close guards). */
export type SideDrawerCloseProps = ComponentProps<typeof DrawerClose>;

"use client";

import { createContext, useCallback, useEffect, useId, useMemo, useRef, useState, type CSSProperties } from "react";

import { cn, classNameWith } from "../../lib/cn";
import { StateLightLayer } from "../../lib/state-light";
import { DrawerContent, type DrawerContentProps } from "../../drawer/drawer";
import { useMergedRef } from "../../lib/form";
import { type SideDrawerSize, sideDrawerSizes, firstField, useSideDrawerContext } from "./model";
import { ResizeHandle } from "./resize";
import { NoticeAnnouncer } from "./header";

/* ---------- Content (the panel) ---------- */

/** Scroll position of the body, shared with the header / footer for their edge shadows. */
export type ScrollState = { atTop: boolean; atBottom: boolean };
/** The scroll state of a body that does not scroll. @internal */
export const SCROLL_REST: ScrollState = { atTop: true, atBottom: true };
/** Shares the body scroll state with the header and footer. @internal */
export const ScrollContext = createContext<{ scroll: ScrollState; setScroll: (state: ScrollState) => void }>({
  scroll: SCROLL_REST,
  setScroll: () => undefined,
});

/**
 * Props of `SideDrawerContent`: the props of `DrawerContent` minus the ones it sets itself, plus its
 * own options.
 */
export type SideDrawerContentProps = Omit<DrawerContentProps, "showClose" | "handle" | "keyboardAware" | "inset"> & {
  /**
   * Float the panel off the screen edges with a full radius, a lit leading edge and an accent aura spilling onto the
   * page (like an iOS 26 sheet). `false` attaches it flush to the edge (the old look). Default true.
   */
  inset?: boolean;
  /**
   * Lights the panel while a `SideDrawerForm` inside it saves (accent glow) or has saved or failed (green, red): a lit
   * edge and a light pool on the glass's own layer (`data-state` on the panel). The seal and the lit leading edge stay.
   * @default true
   */
  stateLight?: boolean;
  /** Width: sm 24rem · md 32rem · lg 40rem · xl 48rem. Full width under 640px. Default "md". */
  size?: SideDrawerSize;
  /** A handle on the free edge to drag (or arrow-key) the width. Hidden under 640px. Default false. */
  resizable?: boolean;
  /** Starting width in px when resizable (instead of `size`). */
  defaultWidth?: number;
  /** Sets the narrowest width in px when resizing. Default 320. */
  minWidth?: number;
  /** Widest width in px when resizing (never more than the screen minus 3rem). */
  maxWidth?: number;
  /** Remember the resized width under this key (localStorage, per browser). */
  storageKey?: string;
  /** Called when a resize ends (pointer up, a key press, a reset). `null` = back to `size`. */
  onWidthChange?: (width: number | null) => void;
  /**
   * Publish the panel's width as `--sheen-side-drawer-right` (or `-left`) on `<html>` while it is open, so fixed
   * UI in that corner (a toast stack) can move out of its way. Off by default: an inherited custom property on
   * the root element restyles the whole document on every open and close (200 to 290 ms on a 4x-throttled phone
   * for a 3,500-element page), and nothing in SheenUI reads it. Default false.
   */
  publishEdge?: boolean;
};

/** The prefix of the key that stores a resized width. @internal */
export const STORAGE_PREFIX = "sheen:side-drawer:";

/** Reads a stored drawer width, or null. @internal */
export function readStoredWidth(key: string | undefined): number | null {
  if (!key || typeof window === "undefined") return null;
  try {
    const value = Number(window.localStorage.getItem(STORAGE_PREFIX + key));
    return Number.isFinite(value) && value > 0 ? value : null;
  } catch {
    return null;
  }
}

/** Stores a drawer width, or clears it with null. @internal */
export function writeStoredWidth(key: string | undefined, width: number | null) {
  if (!key) return;
  try {
    if (width === null) window.localStorage.removeItem(STORAGE_PREFIX + key);
    else window.localStorage.setItem(STORAGE_PREFIX + key, String(Math.round(width)));
  } catch {
    /* storage blocked (private mode): the width just isn't remembered */
  }
}

/**
 * Dims the panel while a dialog (e.g. "Discard unsaved changes?") is open on top of it. Base UI
 * nests such dialogs in the drawer's portal and skips their backdrop, so the panel steps back
 * itself. A layer over the panel (opacity on the layer only): nothing glass is faded.
 */
export function NestedDialogDim() {
  const ref = useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const root = ref.current?.closest("[data-base-ui-portal]");
    if (!root) return;
    let frame = 0;
    const check = () => {
      frame = 0;
      setVisible(
        Boolean(
          root.querySelector(
            ":is([role='alertdialog'], [role='dialog']):not([data-slot='side-drawer'], [data-ending-style])",
          ),
        ),
      );
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(check);
    };
    const observer = new MutationObserver(schedule);
    observer.observe(root, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["data-ending-style"],
    });
    check();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden
      data-visible={visible || undefined}
      className={cn(
        "pointer-events-none absolute inset-0 z-40 rounded-[inherit] bg-[var(--sheen-scrim,var(--sheen-shadow-far))] opacity-0",
        "transition-opacity duration-(--sheen-duration-base) ease-sheen-out data-visible:opacity-100 forced-colors:hidden",
      )}
    />
  );
}

/**
 * The lit leading edge of a floating panel: a thin accent line along the edge facing the page, with a soft aura
 * spilling outwards. Decorative (a layer over the panel, `pointer-events-none`); `forced-colors` hides it.
 * @internal
 */
export function LitEdge({ side }: { side: "left" | "right" }) {
  const edge = cn(
    "pointer-events-none absolute inset-y-8 z-30 w-0.5 rounded-full forced-colors:hidden",
    side === "right" ? "-start-px" : "-end-px",
  );
  return (
    <>
      <span
        aria-hidden
        data-slot="side-drawer-lit-edge-success"
        className={cn(
          edge,
          "[background-image:linear-gradient(to_bottom,transparent,var(--sheen-success-glow)_30%,var(--sheen-success-glow)_70%,transparent)]",
          "[box-shadow:0_0_36px_10px_var(--sheen-success-glow)] opacity-0 transition-opacity duration-(--sheen-duration-base)",
          "[[data-slot=side-drawer]:has([data-slot=side-drawer-seal])_&]:opacity-100",
        )}
      />
      <span
        aria-hidden
        data-slot="side-drawer-lit-edge"
        className={cn(
          "pointer-events-none absolute inset-y-8 z-30 w-0.5 rounded-full forced-colors:hidden",
          side === "right" ? "-start-px" : "-end-px",
          "[background-image:linear-gradient(to_bottom,transparent,var(--sheen-accent-glow)_30%,var(--sheen-accent-glow)_70%,transparent)]",
          "[box-shadow:0_0_28px_6px_var(--sheen-accent-glow)]",
        )}
      />
    </>
  );
}

/*
 * Opt-in (`publishEdge`). While open, tells fixed UI in the panel's corner how much of the screen edge it covers:
 * --sheen-side-drawer-right (or -left) on <html>, in px. A toast stack can add it to its offset
 * (from 640px up, where the panel isn't full width) to stay clear of the panel's header.
 * Rendered inside the popup, so it runs once the popup is actually in the page. Setting and removing an
 * inherited custom property on <html> restyles the whole document, which is why it is not on by default.
 */
/** Publishes the open drawer's edge as a custom property on the document, so the page can react to it. @internal */
export function EdgePublisher({ open, side }: { open: boolean; side: "left" | "right" }) {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const popup = ref.current?.closest<HTMLElement>("[data-slot='side-drawer']");
    if (!open || !popup) return;
    const root = document.documentElement;
    const name = `--sheen-side-drawer-${side}`;
    // offsetWidth ignores the slide-in transform.
    const publish = () => root.style.setProperty(name, `${popup.offsetWidth}px`);
    publish();
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(publish);
    observer?.observe(popup);
    return () => {
      observer?.disconnect();
      root.style.removeProperty(name);
    };
  }, [open, side]);
  return <span ref={ref} hidden />;
}

/**
 * The glass panel of a `SideDrawer`, portalled to the end of the body. `size` sets the width (sm 24rem to xl 48rem, full width under 640px); `resizable` adds a drag/arrow-key handle on the free edge, with `defaultWidth`, `minWidth` (320),
 * `maxWidth`, `storageKey` (remembers the width in localStorage) and `onWidthChange`; `inset` (default true) floats the panel off the edge with a lit leading edge, `false` attaches it; `initialFocus` overrides where focus goes on open.
 * Every other `DrawerContent` prop passes through.
 *
 * By default focus goes to an element marked `data-autofocus`, else (keyboard / mouse) the first field of a `SideDrawerForm`, else the panel itself so screen readers read its title. On touch screens a field is never focused on open:
 * the on-screen keyboard would cover the panel. With `publishEdge` it also publishes its width as `--sheen-side-drawer-right` / `-left` on the root element, so the page can make room for a non-modal panel.
 *
 * Keyboard: see `SideDrawer`; the resize handle takes ← / → (Shift: bigger steps), Home / End, double-click to reset, and Escape cancels a drag. Accessibility: `role="dialog"`; the resize handle is a labelled `separator` with `aria-valuenow`.
 * Glass and motion: `glass-3` panel sliding from its edge; see `SideDrawer`.
 *
 * @example
 * ```tsx
 * import { SideDrawerContent, SideDrawerHeader } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerContent size="lg" resizable storageKey="order-details">
 *       <SideDrawerHeader title="Order #1042" />
 *     </SideDrawerContent>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerContent({
  size = "md",
  resizable = false,
  defaultWidth,
  minWidth = 320,
  maxWidth,
  storageKey,
  onWidthChange,
  publishEdge = false,
  inset = true,
  stateLight = true,
  initialFocus,
  className,
  viewportClassName,
  backdropClassName,
  style,
  children,
  ref,
  ...props
}: SideDrawerContentProps) {
  const { open, side, labels, popupRef } = useSideDrawerContext("SideDrawerContent");
  const mergedPopupRef = useMergedRef(popupRef, ref);
  const [width, setWidth] = useState<number | null>(() => readStoredWidth(storageKey) ?? defaultWidth ?? null);
  /** The width before a drag started, restored when the drag is cancelled (Escape). */
  const widthBeforeDrag = useRef<number | null>(null);
  // Another size or storage key starts from that key's remembered width (or the size's own).
  const [widthSource, setWidthSource] = useState(`${size}|${storageKey ?? ""}`);
  if (widthSource !== `${size}|${storageKey ?? ""}`) {
    setWidthSource(`${size}|${storageKey ?? ""}`);
    setWidth(readStoredWidth(storageKey) ?? defaultWidth ?? null);
  }
  const [scroll, setScroll] = useState<ScrollState>(SCROLL_REST);
  const scrollContext = useMemo(() => ({ scroll, setScroll }), [scroll]);
  const [resizing, setResizing] = useState(false);
  const popupId = useId();

  /*
   * Where focus goes on open: an element marked data-autofocus, else (keyboard / mouse) the first
   * field of a SideDrawerForm, else the panel itself so screen readers read its title. On touch
   * screens a field is never focused on open: the on-screen keyboard would cover the panel.
   */
  const defaultInitialFocus = useCallback(
    (openType: string) => {
      const popup = popupRef.current;
      if (!popup) return true;
      const marked = popup.querySelector<HTMLElement>("[data-autofocus]");
      if (marked) return marked;
      if (openType !== "touch") {
        const field = firstField(popup.querySelector("[data-side-drawer-form]"));
        if (field) return field;
      }
      return popup;
    },
    [popupRef],
  );

  const commitWidth = useCallback(
    (next: number | null) => {
      setWidth(next);
      writeStoredWidth(storageKey, next);
      onWidthChange?.(next);
    },
    [storageKey, onWidthChange],
  );

  const widthVar = { "--sd-width": width === null ? `${sideDrawerSizes[size]}rem` : `${width}px` } as CSSProperties;

  return (
    <ScrollContext value={scrollContext}>
      <DrawerContent
        ref={mergedPopupRef}
        id={popupId}
        showClose={false}
        handle={false}
        keyboardAware={false}
        inset={inset}
        viewportClassName={cn(
          // A little more air around the floating panel from 640px up (the base margin is 0.5rem, safe areas included).
          inset &&
            "sm:[--sheen-drawer-inset-top:max(0.75rem,env(safe-area-inset-top))] sm:[--sheen-drawer-inset-right:max(0.75rem,env(safe-area-inset-right))] sm:[--sheen-drawer-inset-bottom:max(0.75rem,env(safe-area-inset-bottom))] sm:[--sheen-drawer-inset-left:max(0.75rem,env(safe-area-inset-left))]",
          viewportClassName,
        )}
        backdropClassName={cn(
          // The page recedes on this layer only (never a wrapper of the page: that would flatten its glass), and the
          // panel's accent light spills over it from the panel's edge.
          "[background-image:radial-gradient(ellipse_60%_75%_at_var(--sd-aura-x)_50%,color-mix(in_oklab,var(--sheen-accent-glow)_38%,transparent),transparent_70%)]",
          side === "right" ? "[--sd-aura-x:100%]" : "[--sd-aura-x:0%]",
          backdropClassName,
        )}
        initialFocus={initialFocus ?? defaultInitialFocus}
        data-slot="side-drawer"
        data-resizing={resizing || undefined}
        style={typeof style === "function" ? (state) => ({ ...widthVar, ...style(state) }) : { ...widthVar, ...style }}
        className={classNameWith(className, (extra) =>
          cn(
            "@container/side-drawer w-full sm:w-[min(var(--sd-width),calc(100vw-3rem))]",
            side === "right" ? "ml-auto" : "mr-auto",
            !inset && [
              "max-sm:rounded-none max-sm:border-x-0",
              // Full width, the free edge touches the screen too: keep clear of a landscape notch.
              side === "right" ? "max-sm:pl-[env(safe-area-inset-left)]" : "max-sm:pr-[env(safe-area-inset-right)]",
            ],
            "data-resizing:select-none",
            extra,
          ),
        )}
        {...props}
      >
        {children}
        {inset && <LitEdge side={side} />}
        {stateLight && (
          <StateLightLayer className="[--sl-aura:0.5] [--sl-edge:0.7] [--sl-pool:0.7] [--sl-strength:0.8]" />
        )}
        <NoticeAnnouncer />
        {publishEdge && <EdgePublisher open={open} side={side} />}
        <NestedDialogDim />
        {resizable && (
          <ResizeHandle
            open={open}
            side={side}
            label={labels.resize}
            valueText={labels.resizeValue}
            widerLabel={labels.resizeWider}
            narrowerLabel={labels.resizeNarrower}
            popupRef={popupRef}
            popupId={popupId}
            minWidth={minWidth}
            maxWidth={maxWidth}
            onResize={setWidth}
            onCommit={commitWidth}
            onCancel={() => setWidth(widthBeforeDrag.current)}
            onResizingChange={(next) => {
              if (next) widthBeforeDrag.current = width;
              setResizing(next);
            }}
          />
        )}
      </DrawerContent>
    </ScrollContext>
  );
}

"use client";

import { useContext, type ComponentProps, type ReactNode } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";
import { AnimatePresence, motion } from "motion/react";

import { cn, classNameWith } from "../../lib/cn";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { duration, ease, spring } from "../../motion/tokens";
import { DrawerDescription, DrawerTitle } from "../../drawer/drawer";
import { Kbd } from "../../kbd/kbd";
import { Tooltip } from "../../tooltip/tooltip";
import { CheckCircleIcon, CloseIcon } from "../icons";
import { NoticeContext, useSideDrawerContext } from "./model";
import { ScrollContext } from "./content";

/* ---------- Notice ("Saved", "Archived") ---------- */

/** Says the current notice politely. Lives in the panel, so it works with a modal drawer too. */
export function NoticeAnnouncer() {
  const notice = useContext(NoticeContext);
  return (
    <span role="status" className="sr-only">
      {notice ? <span key={notice.id}>{notice.announce}</span> : null}
    </span>
  );
}

/** Props of `SideDrawerNotice`; each option is documented on its field. */
export type SideDrawerNoticeProps = {
  /** Adds extra classes to the notice. */
  className?: string;
  /** "inline": check + message, for the title row. "badge": just the check, pinned to the corner of an avatar / icon (its parent must be positioned). */
  variant?: "inline" | "badge";
};

/**
 * The visible half of `useSideDrawer().notify()`: a check and a short message that pops in next to the title and fades away. `SideDrawerHeader` renders it; place it yourself in a custom header.
 * Plain text, no glass, so it may fade. On a narrow panel only the check shows (the message is still announced), and with a leading avatar it sits on the avatar's corner instead (`variant="badge"`, its parent must be positioned),
 * so the title row never re-wraps. Hidden from screen readers: the panel's live region speaks for it.
 *
 * Keyboard: none. Accessibility: `aria-hidden`; the message is announced by the panel's polite live region. Glass and motion: the check pops in with a spring and fades out; reduced motion only fades.
 *
 * @example
 * ```tsx
 * import { SideDrawerNotice, SideDrawerTitle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <>
 *       <SideDrawerTitle>Order #1042</SideDrawerTitle>
 *       <SideDrawerNotice />
 *     </>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerNotice({ className, variant = "inline" }: SideDrawerNoticeProps) {
  const notice = useContext(NoticeContext);
  const reduced = useSheenReducedMotion();
  return (
    <AnimatePresence initial={false} mode="wait">
      {notice && (
        <motion.span
          key={notice.id}
          aria-hidden
          data-slot="side-drawer-notice"
          data-variant={variant}
          title={typeof notice.message === "string" ? notice.message : undefined}
          initial={reduced ? { opacity: 0 } : { opacity: 0, scale: variant === "badge" ? 0.3 : 0.6 }}
          animate={{ opacity: 1, scale: 1, transition: reduced ? { duration: duration.fast } : spring.bouncy }}
          exit={{ opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }}
          className={cn(
            variant === "inline"
              ? "inline-flex min-w-0 origin-left items-center gap-1 text-xs font-medium whitespace-nowrap text-sheen-success-text rtl:origin-right"
              : [
                  "pointer-events-none absolute -end-1 -bottom-1 grid size-[1.125rem] place-items-center rounded-full",
                  "bg-[var(--sheen-bg)] text-sheen-success-text forced-colors:bg-[Canvas] forced-colors:text-[CanvasText]",
                ],
            className,
          )}
        >
          <CheckCircleIcon className="size-4 shrink-0" />
          {variant === "inline" && <span className="truncate @max-md/side-drawer:hidden">{notice.message}</span>}
        </motion.span>
      )}
    </AnimatePresence>
  );
}

/* ---------- Header ---------- */

/** Ghost icon button used in drawer headers / footers: 36px, 44px hit area on touch screens. */
export const sideDrawerIconButtonClass = cn(
  "relative inline-flex size-9 shrink-0 items-center justify-center rounded-sheen-md text-sheen-fg-muted [&_svg]:size-[1.125rem]",
  "transition-[color,background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
  "data-popup-open:bg-sheen-hover data-popup-open:text-sheen-fg",
  "aria-disabled:cursor-not-allowed aria-disabled:opacity-40 aria-disabled:hover:bg-transparent aria-disabled:hover:text-sheen-fg-muted",
  "touch-manipulation [-webkit-tap-highlight-color:transparent]",
  "any-pointer-coarse:after:absolute any-pointer-coarse:after:-inset-1",
  "forced-colors:border forced-colors:border-[ButtonText]",
);

/** Props of `SideDrawerCloseButton`: the Base UI `Drawer.Close` props minus the ones it sets itself. */
export type SideDrawerCloseButtonProps = Omit<ComponentProps<typeof BaseDrawer.Close>, "children">;

/**
 * The × button, with an "Esc" tooltip. Closes through the close guards. `SideDrawerHeader` renders it (turn it off with `showClose={false}`); place it yourself in a custom header.
 *
 * Keyboard: Enter or Space closes. Accessibility: a labelled button (`labels.close`) with a 44px hit area on touch screens. Glass and motion: colour transitions only.
 *
 * @example
 * ```tsx
 * import { SideDrawerCloseButton } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerCloseButton />
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerCloseButton({ className, ...props }: SideDrawerCloseButtonProps) {
  const { labels } = useSideDrawerContext("SideDrawerCloseButton");
  return (
    <Tooltip
      content={
        <span className="flex items-center gap-2">
          {labels.close}
          <Kbd>{labels.escapeKey}</Kbd>
        </span>
      }
    >
      <BaseDrawer.Close
        data-slot="side-drawer-close"
        aria-label={labels.close}
        className={classNameWith(className, (extra) => cn(sideDrawerIconButtonClass, extra))}
        {...props}
      >
        <CloseIcon />
      </BaseDrawer.Close>
    </Tooltip>
  );
}

/**
 * Props of `SideDrawerHeader`: the native `<div>` props plus its own options, each documented on its
 * field.
 */
export type SideDrawerHeaderProps = Omit<ComponentProps<"div">, "title"> & {
  /** The drawer's name (rendered as its accessible title). */
  title?: ReactNode;
  /** One line under the title (rendered as the accessible description). */
  description?: ReactNode;
  /** Shows an avatar or icon before the title. */
  leading?: ReactNode;
  /** Next to the title: a status Badge, a count. */
  status?: ReactNode;
  /** Shows the buttons before the ×: Edit, a ⋯ menu. */
  actions?: ReactNode;
  /** Shows the × close button in the header. Default true. */
  showClose?: boolean;
  /** Below the title row: Tabs, filters, a toolbar. */
  children?: ReactNode;
};

/**
 * Sticky header: an optional leading slot, the title with its status, the actions and a close button, with the description underneath. The description runs under the actions too, so on a narrow panel an email or id keeps the full width. Gets a hairline once the body scrolls.
 * `title` is the drawer's accessible name and `description` its description; `leading` is an avatar or icon; `status` a Badge or count; `actions` buttons before the ×; `children` render below the title row (Tabs, filters, a toolbar).
 *
 * Keyboard: the actions and × are normal tab stops. Accessibility: the title is an `h2`; see `SideDrawer`. Glass and motion: flat; the hairline fades in with scroll.
 *
 * @example
 * ```tsx
 * import { Avatar, Badge, SideDrawerHeader } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerHeader
 *       title="Ada Lovelace"
 *       description="ada@example.com"
 *       leading={<Avatar name="Ada Lovelace" />}
 *       status={<Badge>Pro</Badge>}
 *     />
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerHeader({
  title,
  description,
  leading,
  status,
  actions,
  showClose = true,
  className,
  children,
  ...props
}: SideDrawerHeaderProps) {
  const { scroll } = useContext(ScrollContext);
  const hasActions = Boolean(actions) || showClose;
  return (
    <div
      data-slot="side-drawer-header"
      data-scrolled={!scroll.atTop || undefined}
      className={cn(
        "relative z-10 flex shrink-0 flex-col gap-3 border-b border-transparent px-4 pt-4 pb-3 @sm/side-drawer:px-5",
        "transition-[border-color] duration-(--sheen-duration-base) ease-sheen-out data-scrolled:border-sheen-border",
        className,
      )}
      {...props}
    >
      <div
        className={cn(
          "grid min-w-0 items-start gap-x-3 gap-y-1",
          leading
            ? hasActions
              ? "grid-cols-[auto_minmax(0,1fr)_auto]"
              : "grid-cols-[auto_minmax(0,1fr)]"
            : hasActions
              ? "grid-cols-[minmax(0,1fr)_auto]"
              : "grid-cols-1",
        )}
      >
        {leading && (
          <div className="row-span-2 flex items-center">
            <span className="relative inline-flex">
              {leading}
              {/* Narrow panel: the check rides on the avatar, so the title row keeps its shape. */}
              <SideDrawerNotice variant="badge" className="hidden @max-md/side-drawer:grid" />
            </span>
          </div>
        )}
        <div className="flex min-h-9 min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          {title && <SideDrawerTitle>{title}</SideDrawerTitle>}
          {status}
          <SideDrawerNotice className={leading ? "@max-md/side-drawer:hidden" : undefined} />
        </div>
        {hasActions && (
          <div className="-me-1.5 flex items-center gap-0.5">
            {actions}
            {showClose && <SideDrawerCloseButton />}
          </div>
        )}
        {description && (
          <SideDrawerDescription render={<div />} className={cn(leading ? "col-start-2 -col-end-1" : "col-span-full")}>
            {description}
          </SideDrawerDescription>
        )}
      </div>
      {children}
    </div>
  );
}

/** Props of `SideDrawerTitle`: the `DrawerTitle` props, unchanged. */
export type SideDrawerTitleProps = ComponentProps<typeof DrawerTitle>;
/** Props of `SideDrawerDescription`: the `DrawerDescription` props, unchanged. */
export type SideDrawerDescriptionProps = ComponentProps<typeof DrawerDescription>;

/**
 * The drawer's heading. It is the dialog's accessible name. `SideDrawerHeader` renders one from its `title` prop; use this directly in a custom header.
 *
 * Keyboard: none. Accessibility: an `h2` wired as `aria-labelledby`. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { SideDrawerTitle } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerTitle>Order #1042</SideDrawerTitle>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerTitle({ className, ...props }: SideDrawerTitleProps) {
  return (
    <DrawerTitle
      className={classNameWith(className, (extra) =>
        cn(
          "min-w-0 text-base leading-snug font-semibold tracking-tight [overflow-wrap:anywhere] @md/side-drawer:text-lg",
          extra,
        ),
      )}
      {...props}
    />
  );
}

/**
 * Muted helper text under the title. It is the dialog's accessible description. `SideDrawerHeader` renders one from its `description` prop; use this directly in a custom header.
 *
 * Keyboard: none. Accessibility: wired as `aria-describedby`. Glass and motion: none.
 *
 * @example
 * ```tsx
 * import { SideDrawerDescription } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SideDrawerDescription>Visible to your team.</SideDrawerDescription>
 *   );
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function SideDrawerDescription({ className, ...props }: SideDrawerDescriptionProps) {
  return (
    <DrawerDescription
      className={classNameWith(className, (extra) =>
        cn("min-w-0 text-sm text-sheen-fg-muted [overflow-wrap:anywhere]", extra),
      )}
      {...props}
    />
  );
}

"use client";

import { createContext, useContext, useEffect, useMemo, type ReactNode, type RefObject } from "react";
import { Drawer as BaseDrawer } from "@base-ui/react/drawer";

import { useLatest } from "../../hooks/use-latest";
import { type DrawerProps } from "../../drawer/drawer";

/* ---------- Types ---------- */

/** Panel width presets of `SideDrawer` (`sm` 24, `md` 32, `lg` 40, `xl` 48 rem). */
export type SideDrawerSize = "sm" | "md" | "lg" | "xl";

/** Width of each size, in rem. */
export const sideDrawerSizes: Record<SideDrawerSize, number> = { sm: 24, md: 32, lg: 40, xl: 48 };

/**
 * Every user-facing string of `SideDrawer` (accessible names, announcements, placeholders); pass a
 * partial `labels` prop to translate or reword them. Entries that need a count or a name are
 * functions.
 */
export type SideDrawerLabels = {
  /** The × button (and its tooltip). */
  close: string;
  /** Key cap for the Escape key in the × tooltip ("Esc", "Échap"…). */
  escapeKey: string;
  /** The resize handle. */
  resize: string;
  /** Spoken value of the resize handle. */
  resizeValue: (width: number) => string;
  /** Step button that makes the panel wider (the non-drag alternative to the handle, WCAG 2.5.7). */
  resizeWider: string;
  /** Step button that makes the panel narrower. */
  resizeNarrower: string;
};

/**
 * Default English strings of `SideDrawerLabels`; spread it and override single keys to reword. Plain
 * data with no DOM access: safe to read while prerendering. The module is `"use client"`, so a React
 * Server Component receives a client reference instead of the object: read it from a client component.
 */
export const defaultSideDrawerLabels: SideDrawerLabels = {
  close: "Close",
  escapeKey: "Esc",
  resize: "Resize panel",
  resizeValue: (width) => `${Math.round(width)} pixels wide`,
  resizeWider: "Make panel wider",
  resizeNarrower: "Make panel narrower",
};

/** Options for `useSideDrawer().notify()`. */
export type SideDrawerNoticeOptions = {
  /** What screen readers hear (defaults to the message), e.g. "Order #1042 archived". */
  announce?: ReactNode;
  /** How long the notice stays, in ms. */
  duration?: number;
};

/** One in-drawer notice: message, announcement and duration. @internal */
export type Notice = { id: number; message: ReactNode; announce: ReactNode; duration: number };

/**
 * Asked before the drawer closes. Return true to allow it, false to keep it open, or a promise
 * (e.g. the answer of a confirmation dialog). It runs for every way of closing.
 */
export type SideDrawerCloseGuard = () => boolean | Promise<boolean>;

/**
 * The details Base UI passes when a `SideDrawer` opens or closes: the reason, the event and a way to
 * cancel.
 */
export type SideDrawerChangeDetails = BaseDrawer.Root.ChangeEventDetails;

/** Props of `SideDrawer`; each option is documented on its field. */
export type SideDrawerProps = Omit<
  DrawerProps,
  "side" | "snapPoints" | "snapPoint" | "defaultSnapPoint" | "onSnapPointChange" | "labels" | "onOpenChange"
> & {
  /**
   * Called when the drawer opens or closes. `details` is Base UI's event details; it is
   * undefined when a close guard settled later (e.g. after "Discard?") or `requestClose` closed it.
   */
  onOpenChange?: (open: boolean, details?: SideDrawerChangeDetails) => void;
  /** Reading direction: the panel slides from the inline end (right in "ltr", left in "rtl"). Defaults to Base UI's DirectionProvider, then the page's `dir`. */
  dir?: "ltr" | "rtl";
  /** Any UI string (i18n). */
  labels?: Partial<SideDrawerLabels>;
};

/** The state the side drawer parts share. @internal */
export type SideDrawerContextValue = {
  open: boolean;
  /** The physical edge the panel is attached to. */
  side: "left" | "right";
  dir: "ltr" | "rtl";
  modal: SideDrawerProps["modal"];
  labels: SideDrawerLabels;
  popupRef: RefObject<HTMLDivElement | null>;
  /** Close, asking the close guards first (unless `force`). Resolves true when it closed. */
  requestClose: (options?: { force?: boolean }) => Promise<boolean>;
  registerGuard: (guard: SideDrawerCloseGuard) => () => void;
  /** Show a short confirmation next to the header's title (null clears it). */
  notify: (message: ReactNode | null, options?: SideDrawerNoticeOptions) => void;
};

/** Shares the side drawer state with its parts. @internal */
export const SideDrawerContext = createContext<SideDrawerContextValue | null>(null);
/** Kept apart from the main context so a notice only re-renders the header and the live region. */
export const NoticeContext = createContext<Notice | null>(null);

/** Reads the side drawer context, throwing when used outside a side drawer. @internal */
export function useSideDrawerContext(component: string) {
  const context = useContext(SideDrawerContext);
  if (!context) throw new Error(`SheenUI: <${component}> must be used inside <SideDrawer>.`);
  return context;
}

/**
 * The surrounding SideDrawer: `open`, `requestClose()` (runs the close guards), `side`, `dir`, `modal` and `notify(message)`. Returns null outside a SideDrawer.
 *
 * `notify("Archived", { announce: "Order #1042 archived" })` shows a check and the message next to the header's title for a moment, and says `announce` politely. Use it instead of a toast for actions that
 * keep the drawer open: a corner toast would sit on top of the panel's header.
 *
 * @returns The drawer's state and actions, or null when called outside a `SideDrawer`.
 *
 * Accessibility: `notify` writes into a polite live region that lives in the panel, so it works with a modal drawer too.
 *
 * @example
 * ```tsx
 * import { Button, useSideDrawer } from "@sheenui/theme";
 *
 * function ArchiveButton() {
 *   const drawer = useSideDrawer();
 *   return <Button onClick={() => drawer?.notify("Archived", { announce: "Order #1042 archived" })}>Archive</Button>;
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function useSideDrawer() {
  const context = useContext(SideDrawerContext);
  return useMemo(
    () =>
      context
        ? {
            open: context.open,
            side: context.side,
            dir: context.dir,
            modal: context.modal,
            requestClose: context.requestClose,
            notify: context.notify,
          }
        : null,
    [context],
  );
}

/**
 * Ask before the drawer closes. Pass a function returning true (close), false (stay) or a promise of either; pass false / null to turn the guard off. Every way of closing asks the guard first: the ×, Escape,
 * the scrim, a swipe and any `SideDrawerClose` button.
 *
 * Accessibility: when the guard keeps the drawer open, focus stays where it is; show your own confirmation (a dialog) so the person knows why.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { useSideDrawerCloseGuard } from "@sheenui/theme";
 *
 * export function Example() {
 *   const [dirty, setDirty] = useState(false);
 *   useSideDrawerCloseGuard(() => (dirty ? confirm("Discard changes?") : true));
 *   return <input aria-label="Name" onChange={() => setDirty(true)} />;
 * }
 * ```
 *
 * @see /overlays/side-drawer
 */
export function useSideDrawerCloseGuard(guard: SideDrawerCloseGuard | false | null | undefined) {
  const context = useContext(SideDrawerContext);
  const latestRef = useLatest(guard);
  const register = context?.registerGuard;
  useEffect(() => {
    if (!register) return;
    return register(() => (latestRef.current ? latestRef.current() : true));
  }, [register, latestRef]);
}

/** Runs guards one after another; stays synchronous until one of them answers with a promise. */
export function runGuards(guards: SideDrawerCloseGuard[]): boolean | Promise<boolean> {
  for (const [i, guard] of guards.entries()) {
    const verdict = guard();
    if (verdict === false) return false;
    if (verdict !== true) return verdict.then((ok) => (ok ? runGuards(guards.slice(i + 1)) : false));
  }
  return true;
}

/* ---------- Direction ---------- */

/* ---------- Last input: touch or not (keeps the on-screen keyboard shut on touch opens) ---------- */

let lastPointerType = "";
let pointerListeners = 0;
/** Records that the last input was a pointer. @internal */
export const notePointer = (event: globalThis.PointerEvent) => {
  lastPointerType = event.pointerType;
};
/** Records that the last input was the keyboard. @internal */
export const noteKey = () => {
  lastPointerType = "keyboard";
};

/** Tracks whether the last input was a pointer or the keyboard, once for the document. @internal */
export function useTrackPointerType() {
  useEffect(() => {
    if (pointerListeners++ === 0) {
      document.addEventListener("pointerdown", notePointer, true);
      document.addEventListener("keydown", noteKey, true);
    }
    return () => {
      if (--pointerListeners === 0) {
        document.removeEventListener("pointerdown", notePointer, true);
        document.removeEventListener("keydown", noteKey, true);
      }
    };
  }, []);
}

/** True when the last interaction was a finger on a touch screen. */
export function lastInteractionWasTouch() {
  return lastPointerType === "touch";
}

/** The first editable field inside `root`, skipping hidden / disabled / non-tabbable ones. */
export function firstField(root: ParentNode | null | undefined): HTMLElement | null {
  return (
    root?.querySelector<HTMLElement>(
      ":is(input, textarea, select, [role='combobox'], [contenteditable='true']):not([type='hidden'], :disabled, [aria-hidden='true'], [tabindex='-1'], [readonly])",
    ) ?? null
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type KeyboardEvent,
  type PointerEvent,
  type RefObject,
} from "react";

import { useLatest } from "../../hooks/use-latest";
import { cn } from "../../lib/cn";
import { clamp } from "../../lib/math";

/* ---------- Resize handle ---------- */

/** Keeps 3rem of the page visible (matches the CSS clamp). */
export const PAGE_GUTTER = 48;

/** The viewport width, updated on resize. @internal */
export function useViewportWidth() {
  return useSyncExternalStore(
    (onChange) => {
      window.addEventListener("resize", onChange);
      return () => window.removeEventListener("resize", onChange);
    },
    () => window.innerWidth,
    () => 1280,
  );
}

/**
 * Rendered width of an element, kept up to date. 0 until the observer's first report, which arrives right after the
 * element's first layout: reading the rect here, inside the open commit, would force an extra style and layout pass
 * of the panel (the callers fall back to a live measurement while it is 0).
 */
export function useElementWidth(ref: RefObject<HTMLElement | null>) {
  const [width, setWidth] = useState(0);
  useEffect(() => {
    const element = ref.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => setWidth(element.getBoundingClientRect().width));
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref]);
  return width;
}

/** The props of the resize handle. @internal */
export type ResizeHandleProps = {
  open: boolean;
  side: "left" | "right";
  label: string;
  valueText: (width: number) => string;
  widerLabel: string;
  narrowerLabel: string;
  popupRef: RefObject<HTMLDivElement | null>;
  popupId: string;
  minWidth: number;
  maxWidth: number | undefined;
  onResize: (width: number) => void;
  onCommit: (width: number | null) => void;
  /** A drag was cancelled: put the width back. */
  onCancel: () => void;
  onResizingChange: (resizing: boolean) => void;
};

/** The pointer, start position and width of a resize drag. @internal */
export type DragState = { pointerId: number; startX: number; startWidth: number; width: number; target: HTMLElement };

/**
 * The separator on the panel's free edge (WAI-ARIA window splitter): drag it, or focus it and
 * use ← / → (Shift: bigger steps), Home / End. Double-click resets to the size's width; Escape
 * during a drag cancels it. `data-base-ui-swipe-ignore` keeps Base UI's swipe-to-dismiss from
 * claiming the drag.
 */
export function ResizeHandle({
  open,
  side,
  label,
  valueText,
  widerLabel,
  narrowerLabel,
  popupRef,
  popupId,
  minWidth,
  maxWidth,
  onResize,
  onCommit,
  onCancel,
  onResizingChange,
}: ResizeHandleProps) {
  const viewport = useViewportWidth();
  const measured = useElementWidth(popupRef);
  const max = Math.max(minWidth, Math.min(maxWidth ?? Number.POSITIVE_INFINITY, viewport - PAGE_GUTTER));
  const min = Math.min(minWidth, max);
  const fit = (value: number) => clamp(value, min, max);
  const drag = useRef<DragState | null>(null);
  const [dragging, setDragging] = useState(false);
  const frame = useRef(0);
  const latestRef = useLatest({ onResizingChange, onCancel });

  function setDraggingState(next: boolean) {
    setDragging(next);
    latestRef.current.onResizingChange(next);
    // The cursor stays a resize cursor (and text doesn't get selected) wherever the pointer goes.
    document.documentElement.style.cursor = next ? "col-resize" : "";
  }

  /** Ends a drag without keeping its width: Escape, the drawer closing, the handle unmounting. */
  const cancelDrag = useCallback(() => {
    const state = drag.current;
    if (!state) return;
    drag.current = null;
    cancelAnimationFrame(frame.current);
    if (state.target.hasPointerCapture(state.pointerId)) state.target.releasePointerCapture(state.pointerId);
    setDragging(false);
    document.documentElement.style.cursor = "";
    latestRef.current.onResizingChange(false);
    latestRef.current.onCancel();
  }, [latestRef]);

  // Closing mid-drag (Escape is taken by the drag, but a guard or the app may close it) and
  // unmounting both end the drag, so the page never keeps the resize cursor.
  useEffect(() => {
    if (!open) cancelDrag();
  }, [open, cancelDrag]);
  useEffect(
    () => () => {
      cancelAnimationFrame(frame.current);
      if (!drag.current) return;
      drag.current = null;
      document.documentElement.style.cursor = "";
      latestRef.current.onResizingChange(false);
    },
    [latestRef],
  );

  function handlePointerDown(event: PointerEvent<HTMLDivElement>) {
    if (event.button !== 0 || !popupRef.current) return;
    event.preventDefault();
    event.currentTarget.focus({ preventScroll: true });
    event.currentTarget.setPointerCapture(event.pointerId);
    const startWidth = popupRef.current.getBoundingClientRect().width;
    drag.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startWidth,
      width: startWidth,
      target: event.currentTarget,
    };
    setDraggingState(true);
  }

  function handlePointerMove(event: PointerEvent<HTMLDivElement>) {
    const state = drag.current;
    if (state?.pointerId !== event.pointerId) return;
    // The handle is on the panel's left edge when it is attached on the right, and vice versa.
    const delta = side === "right" ? state.startX - event.clientX : event.clientX - state.startX;
    state.width = fit(state.startWidth + delta);
    cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(() => onResize(state.width));
  }

  function endDrag(event: PointerEvent<HTMLDivElement>) {
    const state = drag.current;
    if (state?.pointerId !== event.pointerId) return;
    drag.current = null;
    cancelAnimationFrame(frame.current);
    setDraggingState(false);
    if (Math.abs(state.width - state.startWidth) >= 1) onCommit(state.width);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (drag.current) {
      // Mid-drag: Escape puts the width back (and doesn't close the drawer); other keys wait.
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        cancelDrag();
      }
      return;
    }
    const measuredNow = popupRef.current?.getBoundingClientRect().width ?? 0;
    const current = measured || measuredNow || min;
    const step = event.shiftKey ? 64 : 16;
    const grow = side === "right" ? "ArrowLeft" : "ArrowRight";
    const shrink = side === "right" ? "ArrowRight" : "ArrowLeft";
    let next: number | null = null;
    if (event.key === grow) next = current + step;
    else if (event.key === shrink) next = current - step;
    else if (event.key === "Home") next = min;
    else if (event.key === "End") next = max;
    if (next === null) return;
    event.preventDefault();
    onCommit(fit(next));
  }

  const now = Math.round(measured ? fit(measured) : min);

  const stepBy = (delta: number) => {
    const live = popupRef.current?.getBoundingClientRect().width ?? 0;
    const base = measured > 0 ? measured : live > 0 ? live : min;
    onCommit(fit(base + delta));
  };
  const stepClass = cn(
    "flex size-7 cursor-pointer items-center justify-center rounded-sheen-full border border-sheen-control-border bg-sheen-surface text-sheen-fg any-pointer-coarse:size-11",
    "transition-[background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover",
    "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus",
  );
  const chevron = (d: string) => (
    <svg
      aria-hidden
      viewBox="0 0 24 24"
      className="size-3.5"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.4"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d={d} />
    </svg>
  );
  // "Wider" points away from the panel's edge: left when the panel sits on the right.
  const widerPath = side === "right" ? "M15 6l-6 6 6 6" : "M9 6l6 6-6 6";
  const narrowerPath = side === "right" ? "M9 6l6 6-6 6" : "M15 6l-6 6 6 6";

  return (
    <>
      {/* A focusable separator with a value is the WAI-ARIA window splitter: an interactive widget. */}
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- the focusable, valued separator is the WAI-ARIA window splitter (see above): interactive by design */}
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label={label}
        aria-controls={popupId}
        aria-valuenow={now}
        aria-valuemin={Math.round(min)}
        aria-valuemax={Math.round(max)}
        aria-valuetext={valueText(now)}
        // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- window splitter (see above)
        tabIndex={0}
        data-slot="side-drawer-resize"
        data-base-ui-swipe-ignore=""
        data-dragging={dragging || undefined}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        // Capture can also go away without a pointerup (the element moved, the window lost focus).
        onLostPointerCapture={endDrag}
        onKeyDown={handleKeyDown}
        onDoubleClick={() => onCommit(null)}
        className={cn(
          "group/resize peer/resize absolute inset-y-0 z-30 hidden w-3 cursor-col-resize touch-none items-center justify-center outline-none select-none sm:flex",
          "any-pointer-coarse:w-11",
          side === "right" ? "left-0 -translate-x-1/2" : "right-0 translate-x-1/2",
        )}
      >
        {/* A line along the edge while hovered, focused or dragged. */}
        <span
          aria-hidden
          className={cn(
            "pointer-events-none absolute inset-y-3 left-1/2 w-0.5 -translate-x-1/2 rounded-full bg-sheen-accent opacity-0",
            "transition-opacity duration-(--sheen-duration-fast) ease-sheen-out",
            "group-hover/resize:opacity-50 group-focus-visible/resize:opacity-100 group-data-dragging/resize:opacity-100",
            "forced-colors:bg-[Highlight]",
          )}
        />
        {/* The grip. */}
        <span
          aria-hidden
          className={cn(
            "relative h-9 w-1.5 rounded-full bg-sheen-fg-subtle/55 shadow-[0_0_0_1px_var(--sheen-glass-3-bg)]",
            "transition-[background-color,height] duration-(--sheen-duration-fast) ease-sheen-out",
            "group-hover/resize:bg-sheen-fg-muted group-data-dragging/resize:bg-sheen-accent motion-ok:group-data-dragging/resize:h-12",
            "group-focus-visible/resize:outline-2 group-focus-visible/resize:outline-offset-2 group-focus-visible/resize:outline-sheen-focus group-focus-visible/resize:outline-solid",
            "forced-colors:bg-[CanvasText]",
          )}
        />
      </div>
      {/* Single-pointer alternative to dragging (WCAG 2.5.7): step buttons, always shown on coarse pointers and while the
          handle or a button has keyboard focus. Siblings of the separator (its children are presentational). */}
      <div
        data-base-ui-swipe-ignore=""
        className={cn(
          "peer-focus-visible/resize:flex absolute top-1/2 z-30 hidden -translate-y-1/2 flex-col gap-1 has-[:focus-visible]:flex any-pointer-coarse:sm:flex",
          side === "right" ? "left-0 -translate-x-1/2" : "right-0 translate-x-1/2",
        )}
      >
        <button
          type="button"
          aria-label={widerLabel}
          aria-controls={popupId}
          className={stepClass}
          onClick={() => stepBy(32)}
        >
          {chevron(widerPath)}
        </button>
        <button
          type="button"
          aria-label={narrowerLabel}
          aria-controls={popupId}
          className={stepClass}
          onClick={() => stepBy(-32)}
        >
          {chevron(narrowerPath)}
        </button>
      </div>
    </>
  );
}

